// ─── File: src/main/java/com/bank/analytics/service/TradeAnalyticsService.java ───
package com.bank.analytics.service;

import com.bank.analytics.dto.AnalyticsReport;
import com.bank.analytics.model.Trade;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.stream.*;

@Service
@Slf4j
public class TradeAnalyticsService {

    private final List<Trade> trades = List.of(
        new Trade("TRD-001", "RELIANCE", 100, 2450.50),
        new Trade("TRD-002", "TCS",       50, 3520.00),
        new Trade("TRD-003", "HDFC",     200, 1650.75),
        new Trade("TRD-004", "INFY",     150, 1480.25),
        new Trade("TRD-005", "WIPRO",     80,  420.80)
    );

    public AnalyticsReport analyze() {
        List<String> explanations = new ArrayList<>();

        // ═══ 1. mapToInt — Stream<Trade> → IntStream (no boxing!) ═══
        int totalQuantity = trades.stream()
            .mapToInt(Trade::quantity)    // Stream<Trade> → IntStream (primitives)
            .sum();                       // IntStream.sum() — not available on Stream<Integer>!
        explanations.add("mapToInt + sum(): total quantity = " + totalQuantity + " (zero Integer objects!)");

        // ═══ 2. mapToDouble — Stream<Trade> → DoubleStream ═══
        double totalAmount = trades.stream()
            .mapToDouble(Trade::amount)  // Stream<Trade> → DoubleStream
            .sum();
        explanations.add("mapToDouble + sum(): total amount = " + totalAmount);

        // ═══ 3. average() — returns OptionalDouble ═══
        double averagePrice = trades.stream()
            .mapToDouble(Trade::price)
            .average()
            .orElse(0.0);
        explanations.add("average(): avg price = " + averagePrice);

        // ═══ 4. min() / max() — returns OptionalInt ═══
        int minQty = trades.stream().mapToInt(Trade::quantity).min().orElse(0);
        int maxQty = trades.stream().mapToInt(Trade::quantity).max().orElse(0);
        explanations.add("min/max: qty range [" + minQty + ", " + maxQty + "]");

        // ═══ 5. summaryStatistics() — all 5 stats in one pass ═══
        IntSummaryStatistics stats = trades.stream()
            .mapToInt(Trade::quantity)
            .summaryStatistics();
        Map<String, String> statsMap = Map.of(
            "count", String.valueOf(stats.getCount()),
            "sum", String.valueOf(stats.getSum()),
            "min", String.valueOf(stats.getMin()),
            "max", String.valueOf(stats.getMax()),
            "average", String.valueOf(stats.getAverage()));
        explanations.add("summaryStatistics: 5 stats in ONE pass!");

        // ═══ 6. range / rangeClosed — generate IDs ═══
        List<String> generatedIds = IntStream.rangeClosed(1, 5)
            .mapToObj(i -> "NEW-" + String.format("%03d", i))  // IntStream → Stream<String>
            .toList();
        explanations.add("rangeClosed(1,5) + mapToObj: " + generatedIds);

        // ═══ 7. boxed() — IntStream → Stream<Integer> → List<Integer> ═══
        List<Integer> quantitiesList = trades.stream()
            .mapToInt(Trade::quantity)
            .boxed()                      // IntStream → Stream<Integer>
            .toList();                    // need boxed() because toList() returns List<Integer>
        explanations.add("boxed(): IntStream → Stream<Integer> → " + quantitiesList);

        // ═══ 8. asLongStream — widening ═══
        long longSum = trades.stream()
            .mapToInt(Trade::quantity)
            .asLongStream()               // IntStream → LongStream (avoids overflow for large sums)
            .sum();
        explanations.add("asLongStream: widens int→long for overflow safety: " + longSum);

        return new AnalyticsReport(totalQuantity, totalAmount, averagePrice,
            minQty, maxQty, statsMap, generatedIds, quantitiesList, explanations);
    }
}
```

