// ─── File: src/test/java/com/bank/analytics/service/PrimitiveStreamTest.java ───
package com.bank.analytics.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class PrimitiveStreamTest {

    @Test void intStreamSum() {
        assertThat(IntStream.of(10, 20, 30).sum()).isEqualTo(60);
    }

    @Test void intStreamAverage() {
        assertThat(IntStream.of(10, 20, 30).average()).hasValue(20.0);
    }

    @Test void intStreamMinMax() {
        assertThat(IntStream.of(10, 20, 30).min()).hasValue(10);
        assertThat(IntStream.of(10, 20, 30).max()).hasValue(30);
    }

    @Test void summaryStatisticsOnePass() {
        IntSummaryStatistics stats = IntStream.of(10, 20, 30, 40, 50).summaryStatistics();
        assertThat(stats.getCount()).isEqualTo(5);
        assertThat(stats.getSum()).isEqualTo(150);
        assertThat(stats.getMin()).isEqualTo(10);
        assertThat(stats.getMax()).isEqualTo(50);
        assertThat(stats.getAverage()).isEqualTo(30.0);
    }

    @Test void rangeExclusive() {
        assertThat(IntStream.range(0, 5).toArray()).containsExactly(0, 1, 2, 3, 4);
    }

    @Test void rangeClosedInclusive() {
        assertThat(IntStream.rangeClosed(1, 5).toArray()).containsExactly(1, 2, 3, 4, 5);
    }

    @Test void mapToIntConvertsStreamToPrimitive() {
        record Trade(String symbol, int qty) {}
        int total = List.of(new Trade("A", 10), new Trade("B", 20)).stream()
            .mapToInt(Trade::qty).sum();
        assertThat(total).isEqualTo(30);
    }

    @Test void boxedConvertsPrimitiveToObject() {
        List<Integer> list = IntStream.of(1, 2, 3).boxed().toList();
        assertThat(list).containsExactly(1, 2, 3);
        assertThat(list.get(0)).isInstanceOf(Integer.class);
    }

    @Test void mapToObjConvertsToObjectStream() {
        List<String> labels = IntStream.rangeClosed(1, 3)
            .mapToObj(i -> "TRD-" + i).toList();
        assertThat(labels).containsExactly("TRD-1", "TRD-2", "TRD-3");
    }

    @Test void asLongStreamWidens() {
        long sum = IntStream.of(Integer.MAX_VALUE, 1).asLongStream().sum();
        assertThat(sum).isEqualTo((long) Integer.MAX_VALUE + 1);  // no overflow!
    }
}
